{"path": "parser.mjs", "content": "const SKU_RE = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_RE = /^[0-9]+$/;
const MAX = Number.MAX_SAFE_INTEGER;

function parseInteger(raw, field, lineNumber, { positive }) {
  if (!DIGITS_RE.test(raw)) {
    throw new Error(`Malformed ${field} on line ${lineNumber}: ${JSON.stringify(raw)}`);
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${field} on line ${lineNumber} exceeds Number.MAX_SAFE_INTEGER`);
  }
  if (positive && value <= 0) {
    throw new Error(`Malformed ${field} on line ${lineNumber}: must be positive`);
  }
  return value;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }
  const orders = [];
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === '') continue;
    const lineNumber = i + 1;
    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Malformed row on line ${lineNumber}: expected 3 fields`);
    }
    const sku = fields[0].trim();
    const quantityRaw = fields[1].trim();
    const priceRaw = fields[2].trim();
    if (!SKU_RE.test(sku)) {
      throw new Error(`Malformed SKU on line ${lineNumber}: ${JSON.stringify(sku)}`);
    }
    const quantity = parseInteger(quantityRaw, 'quantity', lineNumber, { positive: true });
    const unitPriceCents = parseInteger(priceRaw, 'unitPriceCents', lineNumber, { positive: false });
    orders.push({ sku, quantity, unitPriceCents });
  }
  return orders;
}

export { MAX };
